// C#: Class with properties and methods

using System;

namespace SmtxSamples
{
    public class Vector2
    {
        public double X { get; set; }
        public double Y { get; set; }

        public Vector2(double x, double y)
        {
            X = x;
            Y = y;
        }

        public double Magnitude() => Math.Sqrt(X * X + Y * Y);

        public Vector2 Add(Vector2 other) => new Vector2(X + other.X, Y + other.Y);

        public Vector2 Scale(double factor) => new Vector2(X * factor, Y * factor);

        public double Dot(Vector2 other) => X * other.X + Y * other.Y;

        public override string ToString() => $"({X:F2}, {Y:F2})";
    }

    class Program
    {
        static void Main()
        {
            var a = new Vector2(3, 4);
            var b = new Vector2(1, 2);

            Console.WriteLine($"a = {a}, magnitude = {a.Magnitude():F2}");
            Console.WriteLine($"a + b = {a.Add(b)}");
            Console.WriteLine($"a * 2 = {a.Scale(2)}");
            Console.WriteLine($"a dot b = {a.Dot(b)}");
        }
    }
}

// C#: Loop examples

using System;
using System.Collections.Generic;

class LoopExamples
{
    static void Main()
    {
        // for loop
        for (int i = 0; i < 5; i++)
        {
            Console.WriteLine($"Iteration {i}");
        }

        // while loop
        int count = 0;
        while (count < 3)
        {
            Console.WriteLine($"Count: {count}");
            count++;
        }

        // foreach over a list
        var fruits = new List<string> { "apple", "banana", "cherry" };
        foreach (var fruit in fruits)
        {
            Console.WriteLine($"Fruit: {fruit}");
        }

        // do-while
        int x = 0;
        do
        {
            Console.WriteLine($"x = {x}");
            x++;
        } while (x < 3);
    }
}

// JavaScript: Asynchronous patterns

// Simple delay utility
function delay(ms) {
  return new Promise((resolve) => setTimeout(resolve, ms));
}

// Promise-based fetch simulation
function fetchUserName(id) {
  return new Promise((resolve, reject) => {
    if (id <= 0) {
      reject(new Error("Invalid ID"));
      return;
    }
    setTimeout(() => resolve(`User_${id}`), 100);
  });
}

// Async/await
async function greetUser(id) {
  try {
    const name = await fetchUserName(id);
    await delay(50);
    return `Hello, ${name}!`;
  } catch (err) {
    return `Error: ${err.message}`;
  }
}

// Promise.all for parallel execution
async function greetAll(ids) {
  const greetings = await Promise.all(ids.map(greetUser));
  return greetings;
}

// Run examples
greetUser(42).then(console.log);
greetUser(-1).then(console.log);
greetAll([1, 2, 3]).then((results) => results.forEach(console.log));

// JavaScript: Function examples

// Arrow function
const greet = (name) => `Hello, ${name}!`;

// Default parameters
function power(base, exponent = 2) {
  return Math.pow(base, exponent);
}

// Rest parameters
function sum(...numbers) {
  return numbers.reduce((total, n) => total + n, 0);
}

// Higher-order function
function applyTwice(fn, value) {
  return fn(fn(value));
}

// Closure counter
function createCounter(start = 0) {
  let count = start;
  return {
    increment() { count += 1; },
    decrement() { count -= 1; },
    value() { return count; },
  };
}

// Usage
console.log(greet("World"));
console.log(power(3, 4));
console.log(sum(1, 2, 3, 4, 5));
console.log(applyTwice((x) => x * 2, 3));

const counter = createCounter(10);
counter.increment();
counter.increment();
counter.decrement();
console.log(counter.value()); // 11

# Python: Class definitions with inheritance

class Animal:
    """Base class representing a generic animal."""

    def __init__(self, name: str, sound: str) -> None:
        self.name = name
        self.sound = sound

    def speak(self) -> str:
        return f"{self.name} says {self.sound}!"

    def __repr__(self) -> str:
        return f"Animal(name={self.name!r})"

class Dog(Animal):
    """A dog that can learn tricks."""

    def __init__(self, name: str) -> None:
        super().__init__(name, "woof")
        self.tricks: list = []

    def learn_trick(self, trick: str) -> None:
        self.tricks.append(trick)

    def perform(self) -> str:
        if not self.tricks:
            return f"{self.name} does not know any tricks yet."
        return f"{self.name} performs: {', '.join(self.tricks)}"

class Cat(Animal):
    """A cat with an indoor preference."""

    def __init__(self, name: str, indoor: bool = True) -> None:
        super().__init__(name, "meow")
        self.indoor = indoor

    def status(self) -> str:
        location = "indoor" if self.indoor else "outdoor"
        return f"{self.name} is an {location} cat."

# Usage
dog = Dog("Rex")
dog.learn_trick("sit")
dog.learn_trick("roll over")
print(dog.speak())
print(dog.perform())

cat = Cat("Whiskers")
print(cat.speak())
print(cat.status())
